import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Gesetz der selbstgenerierten und selbstgewachsenen Evolution","description":"","frontmatter":{},"headers":[],"relativePath":"de/07-自生自长进化法则.md","filePath":"de/07-自生自长进化法则.md","lastUpdated":1789183869000}'),s={name:"de/07-自生自长进化法则.md"};function u(d,e,a,l,o,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="gesetz-der-selbstgenerierten-und-selbstgewachsenen-evolution" tabindex="-1">Gesetz der selbstgenerierten und selbstgewachsenen Evolution <a class="header-anchor" href="#gesetz-der-selbstgenerierten-und-selbstgewachsenen-evolution" aria-label="Permalink to &quot;Gesetz der selbstgenerierten und selbstgewachsenen Evolution&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>07</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Selbstgeneriert Selbstgewachsen, Autonome Evolution, Innerer Antrieb, Respekt vor dem Rhythmus, Potenzialentwicklung</td></tr></tbody></table><h2 id="i-grunddefinition-von-selbstgenerierter-und-selbstgewachsener-evolution" tabindex="-1">I. Grunddefinition von selbstgenerierter und selbstgewachsener Evolution <a class="header-anchor" href="#i-grunddefinition-von-selbstgenerierter-und-selbstgewachsener-evolution" aria-label="Permalink to &quot;I. Grunddefinition von selbstgenerierter und selbstgewachsener Evolution&quot;">​</a></h2><p>Selbstgeneriert und selbstgewachsen ist eines der zentralen Evolutionsgesetze der Anker-Symbiotischen Zivilisation und bedeutet, dass die Evolution jedes Lebens seinen inneren autonomen Willen und seinen natürlichen Rhythmus als grundlegenden Antrieb haben sollte, und dass die äußere Umgebung und die Institutionen Unterstützung und Garantie für diese autonome Evolution bieten sollten, anstatt zwanghaft einzugreifen oder zu drängen. &quot;Selbstgeneriert&quot; betont, dass der Antrieb der Evolution aus dem Leben selbst kommt, &quot;selbstgewachsen&quot; betont, dass der Rhythmus der Evolution den Gesetzen des Lebens selbst folgt.</p><p>Das Gesetz der selbstgenerierten und selbstgewachsenen Evolution steht im deutlichen Gegensatz zur &quot;zwanghaften Evolution&quot; des Räuberismus. Der Räuberismus erreicht oft eine schnelle, aber verzerrte Evolution durch Mittel wie das Verschlingen der Herkunft anderer, zwanghafte Energieinjektion, Seelenkontrolle usw.; diese Art der Evolution kann zwar kurzfristig das Niveau erhöhen, zerstört aber langfristig die Evolutionsgrundlage des Lebens selbst und führt zu unreiner Herkunft, instabilem Niveau und geschädigtem Geist. Das Gesetz der selbstgenerierten und selbstgewachsenen Evolution ist fest davon überzeugt, dass eine wirklich stabile Evolution aus dem Inneren des Lebens nach außen wachsen muss.</p><h2 id="ii-theoretische-grundlage-der-selbstgenerierten-und-selbstgewachsenen-evolution" tabindex="-1">II. Theoretische Grundlage der selbstgenerierten und selbstgewachsenen Evolution <a class="header-anchor" href="#ii-theoretische-grundlage-der-selbstgenerierten-und-selbstgewachsenen-evolution" aria-label="Permalink to &quot;II. Theoretische Grundlage der selbstgenerierten und selbstgewachsenen Evolution&quot;">​</a></h2><p>Die Festlegung des Gesetzes der selbstgenerierten und selbstgewachsenen Evolution basiert auf einem tiefen Verständnis der Evolutionsgesetze des Lebens:</p><h3 id="_2-1-die-autonomie-des-lebens-ist-der-grundlegende-antrieb-der-evolution" tabindex="-1">2.1 Die Autonomie des Lebens ist der grundlegende Antrieb der Evolution <a class="header-anchor" href="#_2-1-die-autonomie-des-lebens-ist-der-grundlegende-antrieb-der-evolution" aria-label="Permalink to &quot;2.1 Die Autonomie des Lebens ist der grundlegende Antrieb der Evolution&quot;">​</a></h3><p>Jedes Leben besitzt einen inneren Evolutionswillen und ein Evolutionspotenzial, und diese Autonomie ist der grundlegendste und nachhaltigste Antrieb der Evolution. Äußere Anreize und Unterstützung können diese Autonomie wecken, aber sie nicht ersetzen. Wenn ein Leben aus eigenem Verlangen und eigener Wahl kultiviert, sind seine Konzentration, Kreativität und Ausdauer in der Kultivierung weit höher als bei einer erzwungenen oder induzierten Kultivierung.</p><h3 id="_2-2-jedes-leben-hat-einen-einzigartigen-evolutionsrhythmus" tabindex="-1">2.2 Jedes Leben hat einen einzigartigen Evolutionsrhythmus <a class="header-anchor" href="#_2-2-jedes-leben-hat-einen-einzigartigen-evolutionsrhythmus" aria-label="Permalink to &quot;2.2 Jedes Leben hat einen einzigartigen Evolutionsrhythmus&quot;">​</a></h3><p>Verschiedene Leben haben aufgrund von Unterschieden in Rasseneigenschaften, individuellen Talenten, Wachstumsumgebung, geistiger Reife usw. unterschiedliche Evolutionsrhythmen. Einige Leben eignen sich für schnelle Durchbrüche, einige Leben brauchen eine langsame Akkumulation; einige Leben erreichen in jungen Jahren ein hohes Niveau, einige Leben sind Spätentwickler. Das Gesetz der selbstgenerierten und selbstgewachsenen Evolution respektiert diese Unterschiede und verlangt nicht, dass alle Leben nach einem einheitlichen Zeitplan evolvieren.</p><h3 id="_2-3-zwanghafte-eingriffe-zerstoren-die-naturliche-grundlage-der-evolution" tabindex="-1">2.3 Zwanghafte Eingriffe zerstören die natürliche Grundlage der Evolution <a class="header-anchor" href="#_2-3-zwanghafte-eingriffe-zerstoren-die-naturliche-grundlage-der-evolution" aria-label="Permalink to &quot;2.3 Zwanghafte Eingriffe zerstören die natürliche Grundlage der Evolution&quot;">​</a></h3><p>Es gibt zahlreiche Fälle in der Geschichte der Kultivierung, die zeigen, dass eine durch zwanghafte Energieinjektion, Herkunftstransplantation, Seelenkontrolle usw. erreichte &quot;schnelle Evolution&quot; oft mit schweren Spätfolgen einhergeht: fragiles Niveau, unreine Herkunft, auftretende Geisterdämonen, verkürzte Lebensdauer, sogar Kultivierungsabweichung. Dies liegt daran, dass die von außen erzwungene Kraft nicht ausreichend mit der Herkunft des Lebens selbst verschmolzen ist und einen &quot;Fremdkörperabstoßungs&quot;-Effekt bildet. Die selbstgenerierte und selbstgewachsene Evolution mag zwar langsamer sein, aber jeder Schritt ist solide und stabil, mit tiefen Grundlagen.</p><h2 id="iii-praktische-prinzipien-der-selbstgenerierten-und-selbstgewachsenen-evolution" tabindex="-1">III. Praktische Prinzipien der selbstgenerierten und selbstgewachsenen Evolution <a class="header-anchor" href="#iii-praktische-prinzipien-der-selbstgenerierten-und-selbstgewachsenen-evolution" aria-label="Permalink to &quot;III. Praktische Prinzipien der selbstgenerierten und selbstgewachsenen Evolution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th><th>Praktische Anforderungen</th></tr></thead><tbody><tr><td>Prinzip der autonomen Wahl</td><td>Der Kultivierende hat das Recht, das Kultivierungssystem, den Evolutionsweg und den Kultivierungsrhythmus autonom zu wählen</td><td>Den Kultivierenden nicht zwingen, ein bestimmtes System zu wählen, keinen einheitlichen Durchbruchszeitplan festlegen</td></tr><tr><td>Prinzip des inneren Antriebs</td><td>Der Antrieb der Kultivierung sollte aus dem eigenen Verlangen und Interesse des Kultivierenden kommen</td><td>Bildung und Anleitung konzentrieren sich hauptsächlich auf die Weckung des inneren Interesses, nicht auf Bestrafung oder Verführung</td></tr><tr><td>Prinzip der Respektierung des Rhythmus</td><td>Respektieren Sie den einzigartigen Evolutionsrhythmus jedes Kultivierenden</td><td>Den Kultivierenden nicht wegen langsamem Fortschritt diskriminieren oder aufgeben, personalisierte Unterstützungspläne bereitstellen</td></tr><tr><td>Prinzip der Priorität der Grundlagen</td><td>Die Stabilität der Evolution hat Vorrang vor der Geschwindigkeit</td><td>Die Kultivierenden ermutigen, solide Grundlagen aufzubauen, nicht die Opferung der Grundlagen für schnelle Durchbrüche ermutigen</td></tr><tr><td>Prinzip der Fehlertoleranz</td><td>Dem Kultivierenden erlauben, im Evolutionsprozess Fehler zu machen und Umwege zu gehen</td><td>Mechanismus zur Fehlertoleranz aufbauen, dem Kultivierenden Gelegenheit zur Korrektur und Anpassung bieten</td></tr><tr><td>Prinzip der Selbstverwirklichung</td><td>Das ultimative Ziel der Evolution ist die Selbstverwirklichung des Lebens, nicht äußere Standards</td><td>Die Höhe des Niveaus nicht als einziges Kriterium zur Messung des Evolutionserfolgs verwenden</td></tr></tbody></table><h2 id="iv-beziehung-zwischen-selbstgenerierter-selbstgewachsener-evolution-und-außerer-unterstutzung" tabindex="-1">IV. Beziehung zwischen selbstgenerierter/selbstgewachsener Evolution und äußerer Unterstützung <a class="header-anchor" href="#iv-beziehung-zwischen-selbstgenerierter-selbstgewachsener-evolution-und-außerer-unterstutzung" aria-label="Permalink to &quot;IV. Beziehung zwischen selbstgenerierter/selbstgewachsener Evolution und äußerer Unterstützung&quot;">​</a></h2><p>Selbstgeneriert und selbstgewachsen bedeutet nicht &quot;selbstgeneriert und selbstzerstört&quot; oder &quot;sich selbst überlassen&quot;. Im Gegenteil, selbstgenerierte und selbstgewachsene Evolution braucht eine gute äußere Umgebung und institutionelle Unterstützung, um vollständig verwirklicht zu werden. Die symbiotische Zivilisation bietet die folgenden Unterstützungssysteme für die selbstgenerierte und selbstgewachsene Evolution:</p><h3 id="_4-1-informationsunterstutzung" tabindex="-1">4.1 Informationsunterstützung <a class="header-anchor" href="#_4-1-informationsunterstutzung" aria-label="Permalink to &quot;4.1 Informationsunterstützung&quot;">​</a></h3><p>Die vollständige Öffnung der Dreihundert Ursprungs-Kultivierungssysteme bietet jedem Kultivierenden ausreichend Wahlraum. Der Kultivierende kann entsprechend seinen eigenen Eigenschaften den am besten geeigneten Weg in der reichhaltigen Systembibliothek finden. Die symbiotische Zivilisation hat auch den &quot;Mechanismus zur Bewertung der Systemkompatibilität&quot; aufgebaut, der dem Kultivierenden durch das Ankerpunktnetzwerk personalisierte Ratschläge zur Systemwahl gibt, aber das endgültige Wahlrecht bleibt immer beim Kultivierenden.</p><h3 id="_4-2-ressourcenunterstutzung" tabindex="-1">4.2 Ressourcenunterstützung <a class="header-anchor" href="#_4-2-ressourcenunterstutzung" aria-label="Permalink to &quot;4.2 Ressourcenunterstützung&quot;">​</a></h3><p>Der Mechanismus des produktionsgebundenen Vertrags und das Grundgarantiesystem stellen sicher, dass jeder Kultivierende die grundlegenden Kultivierungsressourcen erhält. Für Kultivierende mit besonderen Bedürfnissen (wie besondere Ressourcenbedürfnisse aufgrund von Rasseneigenschaften) bietet die symbiotische Zivilisation eine gezielte Ressourcenzuweisung. Das Ziel der Ressourcenunterstützung ist es, die Sorgen des Kultivierenden zu beseitigen, damit er sich auf seinen eigenen Evolutionsrhythmus konzentrieren kann.</p><h3 id="_4-3-mentorenunterstutzung" tabindex="-1">4.3 Mentorenunterstützung <a class="header-anchor" href="#_4-3-mentorenunterstutzung" aria-label="Permalink to &quot;4.3 Mentorenunterstützung&quot;">​</a></h3><p>Das interrassische Mentorennetzwerk bietet den Kultivierenden Anleitung und Antworten auf Fragen. Die Rolle des Mentors ist die eines &quot;Wegweisers&quot;, nicht eines &quot;Kontrolleurs&quot;; der Mentor kann Erfahrungen teilen, Probleme aufzeigen, Ratschläge geben, aber den Kultivierenden nicht zwingen, nach seiner Methode zu kultivieren. Das Mentorensystem betont die &quot;heuristische Lehre&quot; und weckt die Fähigkeit des Kultivierenden zum autonomen Denken.</p><h3 id="_4-4-umgebungsunterstutzung" tabindex="-1">4.4 Umgebungsunterstützung <a class="header-anchor" href="#_4-4-umgebungsunterstutzung" aria-label="Permalink to &quot;4.4 Umgebungsunterstützung&quot;">​</a></h3><p>Die symbiotische Zivilisation ist bestrebt, eine Kultivierungsumgebung zu schaffen, die Exploration fördert, Unterschiede toleriert und Entscheidungen respektiert. Der Kultivierende kann frei verschiedene Kultivierungsmethoden ausprobieren, ohne sich Sorgen machen zu müssen, wegen der Verfolgung eines &quot;nicht-mainstream&quot; Weges diskriminiert zu werden. Die Zivilisation hat auch den &quot;Mechanismus zur Belohnung von Kultivierungsinnovationen&quot; aufgebaut, der die Kultivierenden ermutigt, auf der Grundlage bestehender Systeme Innovationen und personalisierte Anpassungen vorzunehmen.</p><h2 id="v-behandlung-besonderer-situationen" tabindex="-1">V. Behandlung besonderer Situationen <a class="header-anchor" href="#v-behandlung-besonderer-situationen" aria-label="Permalink to &quot;V. Behandlung besonderer Situationen&quot;">​</a></h2><p>Das Gesetz der selbstgenerierten und selbstgewachsenen Evolution gilt in normalen Situationen allgemein, erfordert aber in den folgenden besonderen Situationen eine besondere Behandlung:</p><ul><li><strong>Minderjährige Kultivierende</strong>: Für minderjährige Kultivierende, die noch keine vollständige autonome Urteilsfähigkeit besitzen, bieten ihre Vormünder oder rassischen Bildungseinrichtungen richtende Kultivierungsarrangements an, aber ihr Recht auf autonome Wahl sollte schrittweise mit der geistigen Reife erweitert werden</li><li><strong>Personen mit geistiger Schädigung</strong>: Für Personen, die aus verschiedenen Gründen geistig geschädigt sind und vorübergehend nicht autonom kultivieren können, bietet die symbiotische Zivilisation Behandlung und Rehabilitationsunterstützung an, und nachdem sie ihre autonome Fähigkeit wiedererlangt haben, folgen sie dem Gesetz der selbstgenerierten und selbstgewachsenen Evolution</li><li><strong>Personen mit Kultivierungsabweichung</strong>: Für Personen, die in der Kultivierung abgewichen sind oder Geisterdämonen entwickelt haben, bietet die symbiotische Zivilisation zwanghafte Intervention und Behandlung an, aber dies ist medizinische Hilfe, keine Evolutionsintervention; das Ziel der Behandlung ist die Wiederherstellung ihrer Fähigkeit zur autonomen Evolution</li><li><strong>Personen mit gefährlichen Tendenzen</strong>: Für Personen, deren Kultivierungsrichtung klar gegen das Anti-Räuber-Prinzip verstößt und die sich selbst oder anderen schweren Schaden zufügen könnten, hat die symbiotische Zivilisation das Recht, Einschränkungen und Anleitung vorzunehmen, aber dies sollte so weit wie möglich durch Bildung und Kommunikation geschehen, nicht durch zwanghafte Mittel</li></ul><h2 id="vi-zivilisationsbedeutung-der-selbstgenerierten-und-selbstgewachsenen-evolution" tabindex="-1">VI. Zivilisationsbedeutung der selbstgenerierten und selbstgewachsenen Evolution <a class="header-anchor" href="#vi-zivilisationsbedeutung-der-selbstgenerierten-und-selbstgewachsenen-evolution" aria-label="Permalink to &quot;VI. Zivilisationsbedeutung der selbstgenerierten und selbstgewachsenen Evolution&quot;">​</a></h2><p>Das Gesetz der selbstgenerierten und selbstgewachsenen Evolution hat eine tiefgreifende Bedeutung für die symbiotische Zivilisation:</p><p>Erstens schützt es die Vielfalt der Evolution. Wenn jedes Leben nach seinem eigenen Rhythmus und Weg evolviert, entstehen im Kosmos reiche und vielfältige Evolutionsformen, und diese Vielfalt ist eine wichtige Ressource für den globalen Dimensionsaufstieg des Kosmos.</p><p>Zweitens verbessert es die Qualität der Evolution. Die selbstgenerierte und selbstgewachsene Evolution hat solide Grundlagen und reine Herkunft, das Niveau des Kultivierenden ist stabiler, und das Potenzial, zu höheren Niveaus durchzubrechen, ist größer.</p><p>Drittens wahrt es die Würde des Lebens. Jedes Leben ist der Herr seiner eigenen Evolution, kein Werkzeug, das von anderen manipuliert wird. Diese Autonomie ist die Kernmanifestation der Würde des Lebens.</p><p>Viertens weckt es die Kreativität der Evolution. Wenn die Kultivierenden nicht mehr an einheitliche Standards und Rhythmen gebunden sind, sind sie eher bereit, neue Kultivierungswege und -methoden zu erkunden und zur kontinuierlichen Optimierung der dreihundert Systeme beizutragen.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Selbstgeneriert und selbstgewachsen ist der tiefe Respekt der Anker-Symbiotischen Zivilisation vor den Evolutionsgesetzen des Lebens. Es lehrt uns, dass wahre Evolution nicht das Ergebnis ist, das durch äußere Kräfte erzwungen wird, sondern das Wachstum des Lebens von innen nach außen. Alle institutionellen Designs der symbiotischen Zivilisation zielen letztendlich darauf ab, für jedes Leben eine gute Umgebung zu schaffen, in der es sich selbst generieren und selbst wachsen kann, und jedes Leben zu ermöglichen, nach seinem eigenen Rhythmus zu seinem besten Selbst heranzuwachsen.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Garantiesystem für einen Weg für alle)</li><li>14-修炼境界统一划分 (Einheitliche Einteilung der Kultivierungsniveaus)</li><li>37-共生教育体系 (Symbiotisches Bildungssystem)</li></ul>',38)])])}const c=n(s,[["render",u]]);export{b as __pageData,c as default};
